create table snapshots (item_id uuid primary key, owner_id uuid not null references auth.users(id), snapshot_date date not null, name text not null, kind text not null check (kind in ('asset','liability')), category text not null, amount numeric(14,2) not null, currency text not null, institution text, notes text, created_at timestamptz not null default now());
create table transactions (transaction_id uuid primary key, owner_id uuid not null references auth.users(id), description text not null, type text not null check (type in ('income','expensive')), amount numeric(14,2) not null, category text not null, transaction_date date not null, created_at timestamptz not null default now());
create table qa_queries (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), channel text not null check (channel in ('mcp','action')), tool_name text not null, input jsonb not null, row_count integer not null, created_at timestamptz not null default now());
create table pending_transaction_changes (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), operation text not null check (operation in ('create','edit','delete')), target_transaction_id uuid, proposed_fields jsonb, created_at timestamptz not null default now(), expires_at timestamptz not null default (now() + interval '5 minutes'));
create table transaction_mutations (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), channel text not null check (channel in ('mcp','action')), tool_name text not null default 'confirm_transaction_change', operation text not null check (operation in ('create','edit','delete')), transaction_id uuid, actor text not null default 'gio', outcome text not null check (outcome in ('success','failure')), created_at timestamptz not null default now());
create table exchange_rates (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), currency text not null, rate_to_cop numeric(18,6) not null, effective_date date not null, updated_at timestamptz not null default now(), unique(owner_id,currency,effective_date));
create table system_state (owner_id uuid primary key references auth.users(id), pfm_gio_migration_locked boolean not null default false, locked_at timestamptz);
create index idx_snapshots_owner_date on snapshots(owner_id, snapshot_date); create index idx_transactions_owner_date on transactions(owner_id, transaction_date); create index idx_transactions_owner_category on transactions(owner_id, category); create index idx_exchange_rates_owner_currency_date on exchange_rates(owner_id,currency,effective_date desc);
alter table snapshots enable row level security; alter table transactions enable row level security; alter table qa_queries enable row level security; alter table pending_transaction_changes enable row level security; alter table transaction_mutations enable row level security; alter table exchange_rates enable row level security; alter table system_state enable row level security;
create policy "owner snapshots" on snapshots for all using (owner_id = auth.uid()) with check (owner_id = auth.uid()); create policy "owner transactions" on transactions for all using (owner_id = auth.uid()) with check (owner_id = auth.uid()); create policy "owner qa" on qa_queries for all using (owner_id = auth.uid()) with check (owner_id = auth.uid()); create policy "owner pending" on pending_transaction_changes for all using (owner_id = auth.uid()) with check (owner_id = auth.uid()); create policy "owner mutations" on transaction_mutations for all using (owner_id = auth.uid()) with check (owner_id = auth.uid()); create policy "owner rates" on exchange_rates for all using (owner_id = auth.uid()) with check (owner_id = auth.uid()); create policy "owner state" on system_state for all using (owner_id = auth.uid()) with check (owner_id = auth.uid());
